using System.Runtime.CompilerServices;
using DeskCanvas.App.Services;
internal static class V20SpectrumRelativeTests{[ModuleInitializer]internal static void Run(){var loud=SpectrumRelativeMath.FromLinear([.1,.2,1,.3,.05,.01,.01]);var quiet=SpectrumRelativeMath.FromLinear([.001,.002,.01,.003,.0005,.0001,.0001]);for(var i=0;i<loud.Length;i++)if(Math.Abs(loud[i]-quiet[i])>.001)throw new InvalidOperationException("relative spectrum depends on volume");var other=SpectrumRelativeMath.FromLinear([1,.3,.2,.1,.02,.01,.01]);if(other[0]<=other[2])throw new InvalidOperationException("frequency peak was not retained");if(SpectrumRelativeMath.FromLinear(new double[7]).Any(x=>x!=0))throw new InvalidOperationException("digital silence was not gated");Console.WriteLine("PASS v2.0 relative spectrum normalization");}}
